{
  "message": "Thanks — I checked Rho‑Bank’s docs for the EcoCard.",
  "correction": {
    "what_the_kb_says": "The EcoCard referral bonus is $50 per successful referral (not $200).",
    "qualifying_spend": "The referred person must be approved and spend at least $500 within 60 days of account opening."
  },
  "additional_details": {
    "annual_limit": "You can earn up to 7 EcoCard referral bonuses per calendar year.",
    "payout_timing": "The bonus typically posts within one to two billing cycles after the referred account meets the $500 requirement.",
    "referral_link_generation": "You (the customer) must generate your unique referral link from the Rho‑Bank mobile app or the online banking referrals center. Internally there is a user-run tool named get_referral_link(user_id: str, card_name: str) that you can run yourself; agents may not generate the link on your behalf.",
    "rolling_limit": "Credit-card referrals are subject to a rolling 7-day limit of 2 referral bonuses; the third (and any subsequent) referral in that window will be automatically denied."
  },
  "next_steps": [
    "I can give you the user tool so you can generate your EcoCard referral link yourself (you'll need to provide your user_id and the exact card name 'EcoCard').",
    "I can walk you through where to find the referrals section in the mobile app or online portal and how to create the link there.",
    "If you believe you received a communication saying $200 for EcoCard, I can transfer you to a human agent to investigate that discrepancy."
  ],
  "ask": "Which option would you like? If you want the user tool now, say “Yes — give me the get_referral_link tool” and I’ll provide it with the exact arguments to run."
}

{
  "message": "Thanks — I checked Rho‑Bank’s knowledge base and here’s what I found and what I can do next.",
  "eco_card_check": {
    "kb_result": "No evidence of a $200 EcoCard referral promo in the knowledge base. The documented EcoCard referral bonus is $50 (referred person must spend $500 within 60 days).",
    "note_on_targeted_offers": "It’s possible a $200 offer could be a targeted promotion delivered by email or in‑app. I cannot verify account‑specific targeted offers without accessing your account."
  },
  "silver_zoom_check": {
    "kb_result": "The Silver Zoom Card referral program in the KB is for referring logistics businesses and offers $150 for a qualifying referral (referred business must complete $7,500 in purchases within 90 days).",
    "program_window": "The KB shows that the Silver Zoom referral program stopped accepting new referrals after 2025-10-01, so new referral links for that promo are not eligible now."
  },
  "what_i_cannot_do_without_permission": "I can’t verify whether a targeted $200 EcoCard offer is active on your account unless you want me to check your account (that requires verifying your identity first).",
  "verification_note": "If you want me to check your account for targeted offers, I’ll need to verify your identity by confirming any 2 of these: date of birth, email, phone number, or address. After verification I must log the verification. Would you like to proceed with verification?",
  "next_steps_options": [
    {
      "option": "A",
      "description": "I’ll help you verify your account so I can check for any targeted EcoCard offers (requires you to confirm 2 of: DOB, email, phone, or address). Do you want to proceed?"
    },
    {
      "option": "B",
      "description": "I can transfer you to a human agent to investigate the $200 EcoCard communication and confirm whether it’s valid for your account."
    },
    {
      "option": "C",
      "description": "We can look for other currently active referral offers in the KB that you might be eligible for (I’ll summarize any active matches)."
    },
    {
      "option": "D",
      "description": "If you already have an eligible card and want to generate a referral link yourself, I can provide the user tool name and exact arguments you should run (get_referral_link(user_id, card_name))."
    }
  ],
  "ask": "Which would you like to do next? If you choose verification (A) say “I want to verify” and I’ll tell you the exact two fields to confirm; if you want the referral tool (D), tell me which card and I’ll provide the exact get_referral_link instructions."
}

{
  "message": "I found the Platinum Rewards Card referral terms in the KB — it pays $100 when a referred friend is approved and spends $1,500 within 90 days. You can generate the referral link yourself. I’ve provided the user tool you can run to create the link.",
  "tool": {
    "name": "get_referral_link",
    "description": "Generate a referral link for a specific credit card to share with friends or family.",
    "arguments_example": {
      "user_id": "<your_user_id>",
      "card_name": "Platinum Rewards Card"
    },
    "instructions": "Run the get_referral_link tool yourself with your own user_id and the exact card name 'Platinum Rewards Card'. When the tool runs successfully it will create a referral record with status 'NO_PROGRESS' and return your unique link to share."
}
